(5634, 'Starlux AKZ Plus Rechargeable Battery Pack', 'p-akzpbattery-starlux-rechargeable-battery-pack', 'P-AKZPBATTERY-_', 'Rechargeable battery pack for the Starlux AKZ Plus Cantilever umbrella. Provides up to 8 hours of battery life for the umbrella built-in LED lighting system. Clamps directly to the cantilever frame and connects via battery pack cord. Power supply not included -- use the power supply included with your Starlux AKZ Plus Cantilever. Battery specs: Input 24VDC 1.5A, Output 22V 0.9A.', 'Rechargeable battery pack for Starlux AKZ Plus Cantilever. Up to 8 hours of battery life. Power supply not included.', 12, 41, '448.00', NULL, NULL, NULL, TRUE, TRUE, FALSE, FALSE, 0, TRUE, '2026-07-02T03:30:25.311Z'::timestamptz, '2026-07-02T03:39:46.743Z'::timestamptz, 0, '{"Assembly Manual (PDF)":"/api/storage/objects/uploads/tg-akzpbattery-manual.pdf"}'::jsonb, '448.00', NULL, 'fixed', '336.00', '[]'::jsonb, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5635, 'EVO Dual-Light Sound Pod', 'evo-dual-light-sound-pod', 'EVO-_', 'The EVO dual-light sound pod is a multifunctional umbrella and table light with built-in surround sound Bluetooth speakers, adding ambiance and entertainment to any outdoor setting. Features 51 LED lights with two color temperature settings, up to 8 hours of battery life, a self-adjusting umbrella clamp, an integrated bass speaker, and a USB port to charge electronic devices (5V output). Water and dust resistant. Power supply included. White unit: 2800k-3200k warm / 6000k-6700k cool, 30 Lumens each. Diameter: 8.68". Weight: 7 lbs.', 'Dual-light sound pod with Bluetooth speaker for umbrellas. 51 LED lights, up to 8 hours battery life. White or Black.', 12, 40, '475.00', NULL, NULL, NULL, TRUE, TRUE, FALSE, FALSE, 0, TRUE, '2026-07-02T03:30:25.311Z'::timestamptz, '2026-07-02T03:30:25.311Z'::timestamptz, 0, NULL, '475.00', NULL, 'fixed', '357.00', '[]'::jsonb, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5636, 'Luna Pro Multicolor Umbrella Light', 'lunapro-multicolor-umbrella-light', 'LUNAPRO-_', 'The Luna Pro adds convenience and ambiance-rich experiences to the outdoors. Enhanced sound and multi-colored lighting options are featured for easily turning any outdoor gathering into an event. Features 160 LED lights, app control via Luna Pro APP (Android and iOS compatible), Bluetooth compatible, up to 6 hours of battery life, color temperature 3000k, self-adjusting clamp, and power supply included. Diameter: 9.84". Weight: 4 lbs.', 'Multicolor umbrella light with Bluetooth speaker and app control. 160 LED lights, up to 6 hours battery life.', 12, 40, '300.00', NULL, NULL, NULL, TRUE, TRUE, FALSE, FALSE, 0, TRUE, '2026-07-02T03:30:25.311Z'::timestamptz, '2026-07-02T03:30:25.311Z'::timestamptz, 0, NULL, '300.00', NULL, 'fixed', '225.00', '[]'::jsonb, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5637, 'Halo Umbrella Light', 'halo-umbrella-light', 'HALO-_', 'The Halo is the evolution of the award-winning Vega light, featuring the same user-friendly clamp-on function with an upgraded modern design. Elevate your outdoor space with the Halo light to add ambiance with style. Features 26 LED lights, up to 6 hours of battery life, color temperature 4000k, 80 Lumens, self-adjusting clamp, rechargeable battery pack and power supply included. Diameter: 9.45". Weight: 3 lbs.', 'Umbrella light with modern design. 26 LED lights, 80 Lumens, up to 6 hours battery life.', 12, 40, '160.00', NULL, NULL, NULL, TRUE, TRUE, FALSE, FALSE, 0, TRUE, '2026-07-02T03:30:25.311Z'::timestamptz, '2026-07-02T03:30:25.311Z'::timestamptz, 0, NULL, '160.00', NULL, 'fixed', '120.00', '[]'::jsonb, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
